const request = $('POST /integrations/test-all').item.json || {};
const body = request.body || {};
const envKey = String(body.environmentKey || 'local');
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const checkedByRaw = body.checkedBy || body.checkedByUserId || null;
const checkedBy = checkedByRaw && uuidPattern.test(String(checkedByRaw)) ? String(checkedByRaw) : null;
const checkedByName = body.checkedByName || body.actorName || checkedByRaw || 'n8n';
const now = new Date().toISOString();
const rows = $items('Fetch Integrations For Test All').map(i => i.json).filter(i => i && i.integration_key);
const health = $('Fetch Live Health Snapshot').item.json || {};
const services = Array.isArray(health.services) ? health.services : [];
function service(name) { return services.find(s => String(s.name || '').toLowerCase() === name.toLowerCase()) || null; }
function fromHealth(integrationKey, displayName) {
  if (integrationKey === 'supabase') { const db = service('Supabase DB'); const storage = service('Supabase Storage'); const bad = [db, storage].find(s => s && !['ok', 'operational'].includes(s.status)); return { status: bad ? 'degraded' : 'operational', message: [db?.detail, storage?.detail].filter(Boolean).join(' | ') || 'Supabase DB and Storage reachable', detail: { db, storage, probe: 'health-workflow' } }; }
  if (integrationKey === 'chroma') { const s = service('ChromaDB'); return { status: s?.status === 'ok' ? 'operational' : (s?.status || 'unreachable'), message: s?.detail || 'Chroma health result unavailable', detail: { service: s, probe: 'health-workflow' } }; }
  if (integrationKey === 'microservices') { const extractor = service('FastAPI Extractor'); const converter = service('Converter Service'); const bad = [extractor, converter].find(s => s && !['ok', 'operational'].includes(s.status)); return { status: bad ? 'degraded' : 'operational', message: [extractor?.detail, converter?.detail].filter(Boolean).join(' | ') || 'Microservice health endpoints reachable', detail: { extractor, converter, probe: 'health-workflow' } }; }
  if (integrationKey === 'n8n') return { status: health.status === 'ok' ? 'operational' : (health.status || 'unreachable'), message: `n8n health workflow returned ${health.status || 'unknown'}`, detail: { healthStatus: health.status, generatedAt: health.generatedAt, probe: 'health-workflow' } };
  if (integrationKey === 'jira') return { status: 'not_configured', message: 'Jira has no read-only live probe in this workflow yet; credential-backed project GET is the next step', detail: { probe: 'pending-credential-backed-node' } };
  if (integrationKey === 'confluence') return { status: 'not_configured', message: 'Confluence has no read-only live probe in this workflow yet; credential-backed space GET is the next step', detail: { probe: 'pending-credential-backed-node' } };
  if (integrationKey === 'openai') return { status: 'not_configured', message: 'OpenAI live validation is intentionally skipped to avoid cost; add a low-cost credential validation if required', detail: { probe: 'cost-guarded' } };
  return { status: 'not_configured', message: `${displayName || integrationKey} has no live probe configured`, detail: { probe: 'not-configured' } };
}
return rows.map(row => {
  let probe = row.enabled ? fromHealth(row.integration_key, row.display_name) : { status: 'not_configured', message: `${row.display_name || row.integration_key} is disabled`, detail: { probe: 'disabled' } };
  const result = { environment_key: row.environment_key || envKey, integration_key: row.integration_key, service_name: row.display_name || row.integration_key, status: probe.status, latency_ms: null, message: probe.message, technical_detail: { ...probe.detail, source: 'live-probe-api', checkedByName }, checked_by: checkedBy, checked_at: now };
  return { json: { environmentKey: row.environment_key || envKey, integrationKey: row.integration_key, status: probe.status, message: probe.message, checkedAt: now, checkedBy, checkedByName, result } };
});

const results = $items('Prepare Live Integration Test Results').map(i => ({ environmentKey: i.json.environmentKey, integrationKey: i.json.integrationKey, status: i.json.status, message: i.json.message, checkedAt: i.json.checkedAt }));
const counts = results.reduce((acc, item) => { acc[item.status] = (acc[item.status] || 0) + 1; return acc; }, {});
return [{ json: { ok: true, generatedAt: new Date().toISOString(), counts, integrations: results } }];
